def __init__(self, n, k, tp, mode=1, sigma=None,
             ncv=None, v0=None, maxiter=None, which="LM", tol=0):
    if k <= 0:
        raise ValueError(f"k must be positive, k={k}")

    if maxiter is None:
        maxiter = n * 10
    if maxiter <= 0:
        raise ValueError(f"maxiter must be positive, maxiter={maxiter}")

    if tp not in 'fdFD':
        # Use `float64` libraries from integer dtypes.
        if np.can_cast(tp, 'd'):
            tp = 'd'
        else:
            raise ValueError("matrix type must be 'f', 'd', 'F', or 'D'")

    if v0 is not None:
        # ARPACK overwrites its initial resid,  make a copy
        self.resid = np.array(v0, copy=True)
        info = 1
    else:
        # ARPACK will use a random initial vector.
        self.resid = np.zeros(n, tp)
        info = 0

    if sigma is None:
        #sigma not used
        self.sigma = 0
    else:
        self.sigma = sigma

    if ncv is None:
        ncv = choose_ncv(k)
    ncv = min(ncv, n)

    self.v = np.zeros((n, ncv), tp)  # holds Ritz vectors
    self.iparam = np.zeros(11, arpack_int)

    # set solver mode and parameters
    ishfts = 1
    self.mode = mode
    self.iparam[0] = ishfts
    self.iparam[2] = maxiter
    self.iparam[3] = 1
    self.iparam[6] = mode

    self.n = n
    self.tol = tol
    self.k = k
    self.maxiter = maxiter
    self.ncv = ncv
    self.which = which
    self.tp = tp
    self.info = info

    self.converged = False
    self.ido = 0


