def func(data, A0, A1, A2, A3, A4, A5):
    """Compute parametric function to fit."""
    a = data['a']
    b = data['b']
    x = data['x']
    return (A0 * b * np.exp(-0.5 * a)
            + np.exp(A1 + 1 / (1 + a) * np.log(x) - A2 * np.exp(-A3 * a)
                     + A4 / (1 + np.exp(A5 * a))))


