    self.constr = constr
    self.jac = jac
    self.barrier_parameter = barrier_parameter
    self.tolerance = tolerance
    self.n_eq = n_eq
    self.n_ineq = n_ineq
    self.enforce_feasibility = enforce_feasibility
    self.global_stop_criteria = global_stop_criteria
