def _update(self, x, f, dx, df, dx_norm, df_norm):
    if self.M == 0:
        return

    self.dx.append(dx)
    self.df.append(df)

    while len(self.dx) > self.M:
        self.dx.pop(0)
        self.df.pop(0)

    n = len(self.dx)
    a = np.zeros((n, n), dtype=f.dtype)

    for i in range(n):
        for j in range(i, n):
            if i == j:
                wd = self.w0**2
            else:
                wd = 0
            a[i,j] = (1+wd)*vdot(self.df[i], self.df[j])

    a += np.triu(a, 1).T.conj()
    self.a = a


