    _dtype = xp.float64
    if xp.isdtype(_x.dtype, "real floating"):
        _dtype = _x.dtype

    # store original functions
    self._orig_fun = fun
    self._orig_jac = jac
    self._orig_hess = hess

    # promotes to floating, ensures that it's a copy
    self.x = xp.astype(_x, _dtype)
    self.x_dtype = _dtype

    self.n = self.x.size
