def expect(self, func=None, args=(), loc=0, scale=1, lb=None, ub=None,
           conditional=False, **kwds):
    _a, _b = -np.pi, np.pi

    if lb is None:
        lb = loc + _a
    if ub is None:
        ub = loc + _b

    return super().expect(func, args, loc,
                          scale, lb, ub, conditional, **kwds)


