def _logpdf(self, x, s2, mu, lmbda, a, b):
    t1 = 0.5 * (np.log(lmbda) - np.log(2 * np.pi * s2))
    t2 = a*np.log(b) - special.gammaln(a).astype(a.dtype)
    t3 = -(a + 1) * np.log(s2)
    t4 = -(2*b + lmbda*(x - mu)**2) / (2*s2)
    return t1 + t2 + t3 + t4


