def _pdf(self, x, s2, mu, lmbda, a, b):
    t1 = np.sqrt(lmbda / (2 * np.pi * s2))
    t2 = b**a / special.gamma(a).astype(a.dtype)
    t3 = (1 / s2)**(a + 1)
    t4 = np.exp(-(2*b + lmbda*(x - mu)**2) / (2*s2))
    return t1 * t2 * t3 * t4


