def __init__(self, x, y, *, rtol=None, max_terms=100, clean_up=True,
             clean_up_tol=1e-13):
    super().__init__(x, y, rtol=rtol, max_terms=max_terms)

    if clean_up:
        self.clean_up(clean_up_tol)


