def __init__(self, data, typecode, size, shape, dimensions,
             attributes=None,
             maskandscale=False):
    self.data = data
    self._typecode = typecode
    self._size = size
    self._shape = shape
    self.dimensions = dimensions
    self.maskandscale = maskandscale

    self._attributes = attributes or {}
    for k, v in self._attributes.items():
        self.__dict__[k] = v


